  const auto last = high ? high->size() : low.size();
  for (std::size_t length = low.size(); length <= last; ++length) {
    const auto first =
        length == low.size() ? low : "1" + std::string(length - 1, '0');
    const auto end =
        high && length == high->size() ? *high : std::string(length, '9');
    if (first <= end)
